package com.cvp.maintenance.adapter.inbound.kafka;
import com.cvp.maintenance.application.InventorySynchronizationService;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class InventoryVehicleChangedListener { final ObjectMapper json; final InventorySynchronizationService sync; InventoryVehicleChangedListener(ObjectMapper j,InventorySynchronizationService s){json=j;sync=s;} @KafkaListener(topics="${maintenance-reminder.integration.inventory.change-topic}") public void onMessage(String payload)throws Exception{JsonNode event=json.readTree(payload);if(!event.hasNonNull("eventId")||!event.hasNonNull("vehicleId")||!event.hasNonNull("sourceVersion")||event.get("sourceVersion").asLong()<1)throw new IllegalArgumentException("Invalid Inventory event");sync.synchronizeIfNewer(event.get("vehicleId").asText(),event.get("sourceVersion").asLong());} }
